import numpy as np
import time


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = np.convolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    num = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _shape(a, p, N):
    x = np.linspace(-1.0, 1.0, N)
    return np.exp(-a * np.abs(x) ** p)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.9 * budget_seconds

    # Ignore start unless it has more than one distinct height.
    use_start = False
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 1 and np.unique(s).size > 1:
            use_start = True

    N_search = 2000
    N_final = 20000

    best_R = -1.0
    best_ap = (1.0, 2.0)

    def evaluate(a, p):
        if a <= 0 or p <= 0:
            return -1.0
        return _R(_shape(a, p, N_search))

    # Coarse grid: a log-spaced in [1e-4, 50], p in [0.3, 8].
    a_grid = np.logspace(np.log10(1e-4), np.log10(50.0), 30)
    p_grid = np.linspace(0.3, 8.0, 30)
    for a in a_grid:
        for p in p_grid:
            r = evaluate(a, p)
            if r > best_R:
                best_R = r
                best_ap = (a, p)
            if time.process_time() > deadline:
                break
        if time.process_time() > deadline:
            break

    # Random points.
    rng = np.random.default_rng(12345)
    n_rand = 500
    for _ in range(n_rand):
        if time.process_time() > deadline:
            break
        la = rng.uniform(np.log(1e-4), np.log(50.0))
        a = np.exp(la)
        p = rng.uniform(0.3, 8.0)
        r = evaluate(a, p)
        if r > best_R:
            best_R = r
            best_ap = (a, p)

    # Local multiplicative pattern search on (a, p).
    a, p = best_ap
    step_a = 0.5
    step_p = 0.5
    min_step = 1e-6
    while time.process_time() < deadline:
        improved = False
        for da in (1.0 + step_a, 1.0 / (1.0 + step_a)):
            for dp in (1.0 + step_p, 1.0 / (1.0 + step_p)):
                na = a * da
                np_ = p * dp
                r = evaluate(na, np_)
                if r > best_R:
                    best_R = r
                    a, p = na, np_
                    improved = True
                    break
            if improved:
                break
        if not improved:
            step_a *= 0.5
            step_p *= 0.5
            if step_a < min_step and step_p < min_step:
                break
        if time.process_time() > deadline:
            break

    best_ap = (a, p)

    # If start is a genuinely nonuniform shape, also consider it directly.
    if use_start:
        s = np.asarray(start, dtype=float).ravel()
        # Resample start to N_search for comparison.
        xs = np.linspace(0.0, 1.0, s.size)
        xt = np.linspace(0.0, 1.0, N_search)
        s_res = np.interp(xt, xs, s)
        r_start = _R(s_res)
        if r_start > best_R:
            # Return the start resampled to N_final.
            xt2 = np.linspace(0.0, 1.0, N_final)
            return np.interp(xt2, xs, s)

    return _shape(best_ap[0], best_ap[1], N_final)

import numpy as np
import time


def _R(h):
    h = np.asarray(h, dtype=float)
    L = np.convolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    s = L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2
    l2 = s.sum() / 3.0
    l1 = h.sum() ** 2
    linf = L.max()
    if linf <= 0 or l1 <= 0:
        return 0.0
    return l2 / (l1 * linf)


def _make(a, b, p, N):
    x = -1.0 + 2.0 * np.arange(N) / (N - 1)
    t = np.maximum(np.abs(x) - b, 0.0)
    return np.exp(-a * t ** p)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    N_eval = 2000
    N_final = 20000

    best = None
    best_R = -1.0

    def consider(a, b, p):
        nonlocal best, best_R
        if a <= 0 or p <= 0 or b < 0 or b > 0.95:
            return
        h = _make(a, b, p, N_eval)
        if not np.all(np.isfinite(h)) or h.sum() <= 0:
            return
        R = _R(h)
        if R > best_R:
            best_R = R
            best = (a, b, p)

    # Include baseline b=0 (generalized Gaussian)
    rng = np.random.default_rng(12345)

    # Random search
    n_rand = 500
    for _ in range(n_rand):
        if time.process_time() > deadline:
            break
        b = rng.uniform(0.0, 0.92)
        a = 10 ** rng.uniform(np.log10(0.05), np.log10(100.0))
        p = rng.uniform(0.5, 5.0)
        consider(a, b, p)

    # Also try some b=0 baselines explicitly
    for a in [0.5, 1.0, 2.0, 5.0, 10.0]:
        for p in [1.0, 1.5, 2.0, 3.0]:
            consider(a, 0.0, p)

    # Coordinate pattern search from best
    if best is not None:
        a, b, p = best
        step_a = 0.5
        step_b = 0.1
        step_p = 0.5
        cur_R = best_R
        while time.process_time() < deadline:
            improved = False
            for da in (-step_a, step_a):
                na = a * np.exp(da)
                consider(na, b, p)
                if best_R > cur_R:
                    a, b, p = best
                    cur_R = best_R
                    improved = True
                    break
            if not improved:
                for db in (-step_b, step_b):
                    nb = b + db
                    consider(a, nb, p)
                    if best_R > cur_R:
                        a, b, p = best
                        cur_R = best_R
                        improved = True
                        break
            if not improved:
                for dp in (-step_p, step_p):
                    np_ = p + dp
                    consider(a, b, np_)
                    if best_R > cur_R:
                        a, b, p = best
                        cur_R = best_R
                        improved = True
                        break
            if not improved:
                step_a *= 0.6
                step_b *= 0.6
                step_p *= 0.6
                if step_a < 1e-3 and step_b < 1e-4 and step_p < 1e-3:
                    break

    if best is None:
        # fallback
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)

    a, b, p = best
    h = _make(a, b, p, N_final)
    return h
